int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir tmp;auto root=std::filesystem::path(tmp.path().toStdWString());DspController controller;CenterSettings settings;settings.values[0]=0;settings.values[13]=1.25;std::string error;CHECK(controller.configureCenter(CENTER_MODULE_ROOT,settings,error));CHECK(controller.configureAligner(CENTER_MODULE_ROOT,error));auto sessionHeader=session(1);StageBusWin32 source,consumer;CHECK(source.create(sessionHeader,error));CHECK(DspSessionDiscovery::write(root/"source.json",sessionHeader,"EXTERNAL",error));CHECK(controller.start(root,root/"source.json",error));auto wait=[&](auto predicate){auto deadline=qpc()+frequency()*3;while(!predicate()){if(qpc()>=deadline||controller.snapshot().state==DspStateCode::Fault)return false;source.heartbeat(qpc());consumer.heartbeat(qpc());Sleep(1);}return true;};CHECK(wait([&]{return controller.snapshot().diag.alignment.loaded;}));CHECK(consumer.open(controller.snapshot().outputSession,error));Planes<10> in;Planes<11> out;auto cycle=[&](uint64_t seq){for(unsigned i=0;i<1024;i++)in.data[0][i]=in.data[1][i]=double((seq-1)*1024+i+1);if(consumer.trySendRequest(request(sessionHeader,seq))!=StageBusIoResult::Ok)return false;StageBusFrameRequest r{};if(!wait([&]{return source.tryReceiveRequest(r)==StageBusIoResult::Ok;}))return false;auto h=header(r);if(source.tryPublish(h,in.in.data())!=StageBusIoResult::Ok)return false;StageBusBlockHeader got{};return wait([&]{return consumer.tryConsume(got,out.out.data())==StageBusIoResult::Ok;})&&!std::memcmp(&h,&got,sizeof(h));};CHECK(cycle(1));CHECK(wait([&]{return controller.snapshot().diag.alignment.valid;}));CHECK(controller.requestAlignment(true));CHECK(wait([&]{return controller.snapshot().diag.alignment.commandSerial==1;}));CHECK(controller.snapshot().diag.alignment.mode==1);CHECK(cycle(2));for(unsigned i=240;i<1024;i++)CHECK(out.data[0][i]==out.data[2][i]);settings.values[13]=2.5;CHECK(controller.requestCenter(settings));CHECK(!controller.requestAlignment(true));CHECK(wait([&]{return controller.snapshot().diag.center.revision==2;}));CHECK(cycle(3));CHECK(wait([&]{return controller.snapshot().diag.alignment.proposed[0]==480;}));CHECK(controller.snapshot().diag.alignment.current[0]==240);CHECK(controller.requestAlignment(false));CHECK(wait([&]{return controller.snapshot().diag.alignment.commandSerial==2;}));CHECK(cycle(4));CHECK(!std::memcmp(in.in[0],out.in[0],8192));controller.stop();CHECK(!controller.snapshot().diag.alignment.loaded);consumer.close();source.close();sessionHeader=session(1);CHECK(source.create(sessionHeader,error));CHECK(DspSessionDiscovery::write(root/"source.json",sessionHeader,"EXTERNAL",error));CHECK(controller.start(root,root/"source.json",error));CHECK(wait([&]{return controller.snapshot().diag.alignment.loaded;}));CHECK(consumer.open(controller.snapshot().outputSession,error));CHECK(cycle(1));CHECK(wait([&]{return controller.snapshot().diag.alignment.valid;}));CHECK(controller.snapshot().diag.alignment.mode==0);CHECK(controller.requestAlignment(true));CHECK(wait([&]{return controller.snapshot().diag.alignment.commandSerial==3;}));CHECK(controller.snapshot().diag.alignment.current[0]==480);CHECK(controller.requestAlignment(false));CHECK(wait([&]{return controller.snapshot().diag.alignment.commandSerial==4;}));controller.stop();std::cout<<"PASS restart and typed UI commands adopted only by worker, stale Center request refused, manual static compensation and explicit bypass\n";}
